<script setup lang="ts">
import {onMounted, ref, watch} from 'vue'
import {BookOpen, Upload, FileText, RefreshCw, Download, Trash2, Send, ShieldCheck} from 'lucide-vue-next'
import MainLayout from '@/components/MainLayout.vue'
import request from '@/utils/request'
import {useAuthStore} from '@/stores/auth'

type Doc={documentId:string;version:number;activeVersion:number;title:string;filename:string;status:string;error:string;attempts:number}
type Source={id:string;title:string;version:number;location:string;text:string;score:number;chunkId:string}
type Reply={answer:string;sources:Source[];retrieval:string;model:string}
type Event={documentId:string;version:number;action:string;status:string;error:string;attempts:number}
const auth=useAuthStore(),docs=ref<Doc[]>([]),events=ref<Event[]>([]),status=ref<Record<string,any>>({})
const busy=ref(false),error=ref(''),notice=ref(''),title=ref(''),editing=ref<Doc>(),file=ref<File>(),fileInput=ref<HTMLInputElement>()
const question=ref(''),messages=ref<{question:string;reply:Reply}[]>([]),preview=ref(''),showEvents=ref(false)
const labels:Record<string,string>={UPLOADED:'已上传',INDEXING:'索引中',READY:'可检索',FAILED:'失败待重试',CLEANUP_PENDING:'删除清理待重试',DELETED:'已删除'}
async function refresh(){[docs.value,status.value,events.value]=await Promise.all([request.get<Doc[]>('/rag/documents'),request.get<Record<string,any>>('/rag/status'),request.get<Event[]>('/rag/events')])}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action()}catch(e:any){error.value=e.message||'操作失败'}finally{busy.value=false}}
function clear(){editing.value=undefined;title.value='';file.value=undefined;if(fileInput.value)fileInput.value.value=''}
function choose(event:Event & any){file.value=event.target.files?.[0];if(file.value&&!title.value)title.value=file.value.name.replace(/\.[^.]+$/,'')}
function edit(doc:Doc){editing.value=doc;title.value=doc.title;file.value=undefined;if(fileInput.value)fileInput.value.value='';notice.value='请选择替换文件。索引成功前保留原可检索版本。'}
async function upload(){await run(async()=>{
  if(!file.value||!title.value.trim())throw Error('请填写标题并选择文件')
  if(file.value.size>2*1024*1024)throw Error('文件最大2MB')
  const body=new FormData();body.append('documentId',editing.value?.documentId||crypto.randomUUID());body.append('version',String((editing.value?.version||0)+1));body.append('title',title.value.trim());body.append('file',file.value)
  const result=await request.post<{status:string;error?:string}>('/rag/documents',body,{timeout:600000})
  notice.value=result.status==='READY'?'向量索引完成，可以提问。':'原件已保存，索引失败：'+result.error
  clear();await refresh()
})}
async function retry(id:string,version:number){await run(async()=>{await request.post('/rag/documents/'+id+'/retry',null,{params:{version},timeout:120000});await refresh();notice.value='重试已完成，请查看处理状态。'})}
async function remove(doc:Doc){if(!confirm('删除“'+doc.title+'”？删除后立即退出检索。'))return;await run(async()=>{const result=await request.delete<{cleanupPending:boolean}>('/rag/documents/'+doc.documentId,{params:{version:doc.version+1}});messages.value=[];preview.value='';await refresh();notice.value=result.cleanupPending?'已退出检索，原件清理待重试。':'文件已删除并退出向量检索。'})}
async function download(doc:Doc){await run(async()=>{
 const blob=await request.get<Blob>('/rag/documents/'+doc.documentId+'/download',{responseType:'blob'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=doc.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
})}
async function inspect(doc:Doc){await run(async()=>{const detail=await request.get<{text:string}>('/rag/documents/'+doc.documentId);preview.value=detail.text||'尚未提取正文，请查看处理错误。'})}
async function ask(){if(!question.value.trim())return;await run(async()=>{const q=question.value.trim();const reply=await request.post<Reply>('/rag/messages',{question:q,mode:'RAG'},{timeout:120000});messages.value.push({question:q,reply});question.value=''})}
watch(()=>auth.currentUser?.id,()=>{docs.value=[];events.value=[];messages.value=[];preview.value='';clear()})
onMounted(()=>run(refresh))
</script>

<template>
 <MainLayout><div class="knowledge-space">
  <header class="knowledge-heading"><div><span class="eyebrow">MOUSE MES · KNOWLEDGE</span><h1><BookOpen :size="28"/>私有知识库</h1><p>把工艺、操作规范与检验资料，变成有据可查的回答。</p></div><span class="private-tag"><ShieldCheck :size="16"/>仅当前账号可见</span></header>
  <div v-if="error" class="feedback error" role="alert">{{error}}</div><div v-if="notice" class="feedback" role="status">{{notice}}</div>
  <div class="knowledge-grid">
   <section class="panel library"><div class="panel-heading"><h2>我的资料 <span>{{docs.length}}</span></h2><button :disabled="busy" aria-label="刷新资料" @click="run(refresh)"><RefreshCw :size="17"/></button></div>
    <form class="upload-form" @submit.prevent="upload"><strong>{{editing?'更新文件 · 保持同一编号':'添加一份资料'}}</strong><label>资料标题<input v-model="title" maxlength="200" placeholder="例如：A100点胶操作规范" required :disabled="busy"/></label><label class="file-picker"><Upload :size="19"/><span>{{file?.name||'选择 PDF / DOCX / TXT / MD / CSV'}}</span><input ref="fileInput" type="file" accept=".pdf,.docx,.txt,.md,.csv" :disabled="busy" @change="choose"/></label><small>单文件最大2MB，正文最多12000字符。扫描版PDF需先做OCR。资料片段会发往配置的云模型处理。</small><div class="button-row"><button class="primary" :disabled="busy||!file">{{busy?'正在处理…':editing?'保存新版本':'上传并建立向量索引'}}</button><button v-if="editing" type="button" :disabled="busy" @click="clear">取消更新</button></div></form>
    <div v-if="!docs.length" class="empty"><FileText :size="32"/><p>还没有资料</p><small>先上传一份操作规范，再在右侧提问。</small></div>
    <article v-for="doc in docs" :key="doc.documentId" class="document"><div class="document-title"><FileText :size="18"/><strong>{{doc.title}}</strong><span :class="['state',doc.status.toLowerCase()]">{{labels[doc.status]||doc.status}}</span></div><p>{{doc.filename}} · v{{doc.version}}<template v-if="doc.activeVersion&&doc.activeVersion!==doc.version"> · 当前检索v{{doc.activeVersion}}</template></p><p v-if="doc.error" class="document-error">{{doc.error}}</p><div class="document-actions"><button :disabled="busy" @click="inspect(doc)">正文</button><button :disabled="busy" @click="download(doc)"><Download :size="13"/>下载{{doc.activeVersion&&doc.activeVersion!==doc.version?'旧版':''}}</button><button :disabled="busy" @click="edit(doc)">更新</button><button v-if="doc.status==='FAILED'" :disabled="busy" @click="retry(doc.documentId,doc.version)">重试原版本</button><button class="danger" :disabled="busy" @click="remove(doc)"><Trash2 :size="13"/>删除</button></div></article>
    <button class="events-toggle" @click="showEvents=!showEvents">{{showEvents?'收起':'查看'}}处理与同步事件</button><div v-if="showEvents" class="events"><article v-for="event in events" :key="event.documentId+event.version"><code>{{event.documentId.slice(0,8)}} · v{{event.version}}</code><p>{{event.action}} · {{labels[event.status]||event.status}} · 尝试{{event.attempts}}次</p><small>{{event.error}}</small><button v-if="event.status==='CLEANUP_PENDING'" :disabled="busy" @click="retry(event.documentId,event.version)">重试清理</button></article></div>
   </section>
   <section class="panel conversation"><div class="panel-heading"><div><h2>资料问答</h2><small>{{status.model||'加载模型配置…'}}</small></div><span class="mode">RAG · 向量检索</span></div><p v-if="!status.chatConfigured||!status.embeddingConfigured" class="config-note">模型密钥尚未配置。请使用任务二启动脚本；嵌入模型需要单独开通权限。</p><p class="graph-note">GraphRAG与融合模式将在任务三代码合并后接入。</p>
    <div class="messages" aria-live="polite"><div v-if="!messages.length" class="welcome"><BookOpen :size="42"/><h3>从你的资料里寻找答案</h3><p>例如：点胶工序需要哪些设备？<br/>回答会显示来源文件、版本和原文位置。</p></div><article v-for="(message,index) in messages" :key="index" class="exchange"><div class="question">{{message.question}}</div><div class="answer">{{message.reply.answer}}</div><details v-for="source in message.reply.sources" :key="source.id" class="source"><summary>[{{source.id}}] {{source.title}} · v{{source.version}} · {{source.location}}<span>相似度 {{source.score.toFixed(3)}}</span></summary><pre>{{source.text}}</pre><small>片段 {{source.chunkId}}</small></details><small class="retrieval">{{message.reply.retrieval}}</small></article><p v-if="busy" class="working">正在处理，请稍候…</p></div>
    <form class="question-form" @submit.prevent="ask"><label class="sr-only" for="rag-question">问题</label><textarea id="rag-question" v-model="question" maxlength="1200" placeholder="针对当前私有库提问…" :disabled="busy" @keydown.ctrl.enter.prevent="ask"/><div><small>{{question.length}} / 1200 · Ctrl+Enter发送</small><button class="primary" :disabled="busy||!question.trim()"><Send :size="16"/>发送</button></div></form>
   </section>
  </div>
  <section v-if="preview" class="panel preview"><div class="panel-heading"><h2>解析正文</h2><button @click="preview=''">关闭</button></div><pre>{{preview}}</pre></section>
 </div></MainLayout>
</template>

<style scoped>
.knowledge-space{max-width:1500px;margin:auto;padding:12px 8px 36px;color:#473d32}.knowledge-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:2px;color:#9b8060}.knowledge-heading h1{display:flex;gap:12px;align-items:center;font-size:29px;font-weight:700;margin:10px 0}.knowledge-heading p{color:#8b7a68;font-size:14px}.private-tag{display:flex;align-items:center;gap:7px;border:1px solid #ddd4c7;background:#f7f3eb;padding:9px 13px;border-radius:24px;font-size:12px;white-space:nowrap}.knowledge-grid{display:grid;grid-template-columns:minmax(310px,.82fr) minmax(400px,1.4fr);gap:22px;align-items:start}.panel{background:#fffdf9;border:1px solid #e4dbce;border-radius:18px;overflow:hidden;box-shadow:0 6px 24px #65543906}.panel-heading{padding:20px 23px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eee7dc;gap:12px}.panel-heading h2{font-size:17px;font-weight:650;margin:0}.panel-heading h2 span{font-size:12px;color:#a68a68;margin-left:7px}.panel-heading small{font-size:11px;color:#9a8b7a}button{cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:5px;font-size:12px;padding:7px 10px;border:1px solid #ded4c4;border-radius:8px;background:#fffdf9}button:disabled{opacity:.45;cursor:wait}.primary{background:#735537;border-color:#735537;color:white}.upload-form{margin:18px;padding:18px;background:#f6f1e8;border-radius:12px;display:flex;flex-direction:column;gap:12px}.upload-form strong{font-size:14px}.upload-form label{font-size:12px;display:flex;flex-direction:column;gap:7px}.upload-form input:not([type=file]){border:1px solid #ded2c0;border-radius:7px;background:white;padding:9px}.file-picker{border:1px dashed #baa78c;border-radius:9px;padding:14px;align-items:center;text-align:center;cursor:pointer}.file-picker input{width:100%;font-size:11px}.upload-form small{font-size:11px;color:#95836b;line-height:1.7}.button-row{display:flex;gap:8px}.empty{padding:30px 20px;text-align:center;color:#a38d70}.empty svg{margin:auto}.empty p{margin-top:10px}.document{padding:18px 22px;border-top:1px solid #eee7dc}.document-title{display:flex;gap:8px;align-items:center}.document-title strong{font-size:14px;flex:1;overflow-wrap:anywhere}.state{font-size:10px;color:#a67a38;background:#f6ecd8;border-radius:5px;padding:4px 6px}.state.ready{color:#52765d;background:#edf3e9}.state.failed{color:#ad5049;background:#fceeea}.document>p{font-size:11px;color:#9c8c77;margin:8px 0;overflow-wrap:anywhere}.document .document-error{color:#b85d50}.document-actions{display:flex;flex-wrap:wrap;gap:5px}.document-actions button{padding:5px 7px;font-size:11px}.danger{color:#b36354}.events-toggle{margin:12px 20px}.events{padding:0 20px 18px;font-size:11px}.events article{padding:10px 0;border-top:1px solid #eee}.events small{color:#b36354}.conversation{display:flex;flex-direction:column;min-height:680px}.mode{font-size:11px;border-radius:20px;padding:7px 12px;background:#efe6d9;color:#80603b}.config-note,.graph-note{font-size:11px;margin:12px 22px 0;color:#9c8a72}.config-note{color:#ae714a}.messages{padding:24px;flex:1;max-height:660px;min-height:380px;overflow:auto}.welcome{text-align:center;color:#b09a7d;padding:70px 15px}.welcome svg{margin:auto}.welcome h3{color:#7b6349;margin:18px 0 10px;font-size:18px}.welcome p{font-size:13px;line-height:1.9}.exchange{margin-bottom:26px}.question{margin-left:15%;background:#eee4d6;border-radius:14px 14px 3px 14px;padding:13px 17px;font-size:14px;white-space:pre-wrap}.answer{padding:18px 0;white-space:pre-wrap;font-size:14px;line-height:1.9}.source{border:1px solid #e7dece;border-radius:8px;margin-bottom:7px;padding:9px 12px;font-size:11px}.source summary{cursor:pointer;line-height:1.8}.source summary span{display:block;color:#aa9678}.source pre,.preview pre{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;font-family:inherit}.source pre{margin:10px 0}.source small,.retrieval{font-size:10px;color:#a3927c;overflow-wrap:anywhere}.question-form{border-top:1px solid #eee7dc;padding:18px 22px}.question-form textarea{resize:vertical;min-height:85px;width:100%;padding:12px;border:1px solid #e0d4c3;border-radius:10px;background:#fff;font-size:13px}.question-form>div{display:flex;align-items:center;justify-content:space-between;margin-top:10px}.question-form small{color:#a28e73;font-size:10px}.feedback{padding:12px 16px;margin-bottom:15px;background:#eef2e7;border-radius:10px;font-size:13px}.feedback.error{background:#fae9e4;color:#ac5144}.preview{margin-top:20px}.preview pre{padding:20px;font-size:13px;max-height:500px;overflow:auto}.working{font-size:12px;color:#9c815d}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:1000px){.knowledge-grid{grid-template-columns:1fr}.knowledge-heading{align-items:flex-start;flex-direction:column}.conversation{min-height:600px}}
</style>
